import{d as g,C as e,o as h,c as u,j as n,a,E as t,a3 as d}from"./chunks/framework.Q4yG9rk_.js";const b=JSON.parse('{"title":"中庸·第14章","description":"《中庸》第 14 章——素其位而行：不陵下、不援上，正己而不求于人；居易以俟命，失诸正鹄则反求诸其身。","frontmatter":{"title":"中庸·第14章","description":"《中庸》第 14 章——素其位而行：不陵下、不援上，正己而不求于人；居易以俟命，失诸正鹄则反求诸其身。","category":"guide","aliases":["第14章","中庸第14章","素其位而行"],"source":["《礼记》","《四书章句集注》"],"outline":[2,3]},"headers":[],"relativePath":"lizhimingde/sishu-wujing/zhongyong/chapter-14.md","filePath":"lizhimingde/sishu-wujing/zhongyong/chapter-14.md","lastUpdated":1790316338000}'),m={name:"lizhimingde/sishu-wujing/zhongyong/chapter-14.md"},x=g({...m,setup(p){const r=[{id:"suwei",label:"素其位而行 · 不愿乎其外",showLabel:!0,sentences:[["君子",{text:"素其位",glossary:"suqiwei"},"而行，不",{text:"愿乎其外",glossary:"yuanhuwai"},"。素富贵，行乎富贵；素贫贱，行乎贫贱；素夷狄，行乎夷狄；素患难，行乎患难；君子",{text:"无入而不自得",glossary:"wurubuzide"},"焉。"]],note:"「君子素其位而行，不愿乎其外」——君子就着当下所处的地位而行（素＝现在、安于），不向外贪求。故「素富贵，行乎富贵；素贫贱，行乎贫贱；素夷狄，行乎夷狄；素患难，行乎患难」：处在什么境地，就在那境地里行其当行。「君子无入而不自得焉」——没有一处不能安然自得。"},{id:"bulinbuyuan",label:"不陵下 · 不援上 · 不怨天不尤人",showLabel:!0,sentences:[["在上位不",{text:"陵",glossary:"ling"},"下，在下位不",{text:"援",glossary:"yuan"},"上，正己而不求于人则无怨。上不怨天，下不尤人。"]],note:"具体说：「在上位不陵下」——在上位不欺凌下属；「在下位不援上」——在下位不攀援上司；「正己而不求于人则无怨」——端正自己而不求于人，便无怨恨；「上不怨天，下不尤人」——上不怨天，下不怪人。"},{id:"fanshu",label:"居易俟命 · 失诸正鹄，反求诸其身",showLabel:!0,sentences:[["故君子",{text:"居易以俟命",glossary:"juyisiming"},"，小人",{text:"行险以徼幸",glossary:"xingxian"},"。子曰：“射有似乎君子；失诸",{text:"正鹄",glossary:"zhenggu"},"，反求诸其身。”"]],note:"「故君子居易以俟命，小人行险以徼幸」——君子安处平易之地以等待天命，小人铤而走险以求侥幸。引孔子论射：「射有似乎君子；失诸正鹄，反求诸其身」——射箭有似君子之道：射不中靶心（正鹄），要回过头来检查自己。"}],o=[{id:"suqiwei",term:"素其位",pinyin:"sù qí wèi",meaning:"安于现在所处之位。素：犹「见在」（现在）。朱注：「但因见在所居之位而为其所当为。」"},{id:"yuanhuwai",term:"不愿乎其外",pinyin:"bù yuàn hū qí wài",meaning:"不羡慕本位之外。愿：慕。"},{id:"wurubuzide",term:"无入而不自得",pinyin:"wú rù ér bù zì dé",meaning:"无论处在什么境遇，都安然自得。"},{id:"ling",term:"陵",pinyin:"líng",meaning:"欺凌。陵下：欺凌下属。"},{id:"yuan",term:"援",pinyin:"yuán",meaning:"攀援。援上：攀附上级。"},{id:"juyisiming",term:"居易以俟命",pinyin:"jū yì yǐ sì mìng",meaning:"居于平易之地以等待天命。易：平地。俟：等待。"},{id:"xingxian",term:"行险以徼幸",pinyin:"xíng xiǎn yǐ jiǎo xìng",meaning:"走险路以求侥幸。徼：求。幸：所不当得而得者。"},{id:"zhenggu",term:"正鹄",pinyin:"zhèng gǔ",meaning:"箭靶。画布为「正」（音征），栖皮为「鹄」。"}];return(y,i)=>{const l=e("DaoTextReading"),s=e("DaoKeywordCards");return h(),u("div",null,[i[0]||(i[0]=n("h1",{id:"中庸·第14章",tabindex:"-1"},[a("中庸·第14章 "),n("a",{class:"header-anchor",href:"#中庸·第14章","aria-label":'Permalink to "中庸·第14章"'},"​")],-1)),i[1]||(i[1]=n("h2",{id:"【原典层】原文",tabindex:"-1"},[a("【原典层】原文 "),n("a",{class:"header-anchor",href:"#【原典层】原文","aria-label":'Permalink to "【原典层】原文"'},"​")],-1)),i[2]||(i[2]=n("p",null,[a("第十四章讲「素其位而行」：各安其位、不慕于外，进而「正己而不求于人」；末以射箭作喻——"),n("strong",null,"射不中靶，先反求自身"),a("。默认竹简沉浸通读；切「经典阅读」可点生词。")],-1)),t(l,{colophon:"素其位而行 · 居易俟命 · 反求诸身",tone:"ink",sections:r,glossary:o,"default-mode":"slips","aria-label":"中庸·第14章 原文"}),i[3]||(i[3]=n("h2",{id:"【原典层】注音与字词",tabindex:"-1"},[a("【原典层】注音与字词 "),n("a",{class:"header-anchor",href:"#【原典层】注音与字词","aria-label":'Permalink to "【原典层】注音与字词"'},"​")],-1)),t(s,{items:[{term:"素其位",pinyin:["sù","qí","wèi"],meaning:"安于现在所处之位。素：见在（现在）。"},{term:"不愿乎其外",pinyin:["bù","yuàn","hū","qí","wài"],meaning:"不羡慕本位之外。愿：慕。"},{term:"无入而不自得",pinyin:["wú","rù","ér","bù","zì","dé"],meaning:"无论处在什么境遇，都安然自得。"},{term:"陵",pinyin:["líng"],meaning:"欺凌。陵下，即欺下。"},{term:"援",pinyin:["yuán"],meaning:"攀援。援上，即攀附。一上一下，各守其分。"},{term:"居易以俟命",pinyin:["jū","yì","yǐ","sì","mìng"],meaning:"居于平易之地以待天命。易：平地。"},{term:"正鹄",pinyin:["zhèng","gǔ"],meaning:"箭靶。「失诸正鹄，反求诸其身」——射不中靶，回头在自己身上找原因。"}]}),i[4]||(i[4]=d('<p>全篇生词的完整释义在<a href="/Dao/reference/glossary/">字词释义字典</a>中统一维护。</p><h2 id="【原典层】白话译文" tabindex="-1">【原典层】白话译文 <a class="header-anchor" href="#【原典层】白话译文" aria-label="Permalink to &quot;【原典层】白话译文&quot;">​</a></h2><p><strong>素其位而行 · 不愿乎其外</strong>：君子安于现在所处的位置而行，不羡慕本位之外。处在富贵，就做富贵中该做的事；处在贫贱，就做贫贱中该做的事；处在夷狄之地，就做那里该做的事；处在患难，就做患难中该做的事——君子无处不安然自得。</p><p><strong>不陵下 · 不援上 · 不怨天不尤人</strong>：在上位不欺凌下属，在下位不攀附上级；端正自己而不求于人，就无所怨：上不怨天，下不尤人。</p><p><strong>居易俟命 · 反求诸其身</strong>：所以君子居平易之地以等待天命，小人走险路以求侥幸。孔子说：「射箭有点像君子：射不中靶，回头在自身找原因。」</p><h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-这一篇在说什么" tabindex="-1">象：这一篇在说什么 <a class="header-anchor" href="#象-这一篇在说什么" aria-label="Permalink to &quot;象：这一篇在说什么&quot;">​</a></h3><p>第十四章由三节组成：</p><ol><li><strong>素其位而行</strong>：处在什么位，就行什么事（富贵、贫贱、夷狄、患难），「无入而不自得」</li><li><strong>正己而不求于人</strong>：不陵下、不援上，上不怨天、下不尤人</li><li><strong>居易以俟命</strong>：与「小人行险以徼幸」相对；末以射箭作喻——<strong>失诸正鹄，反求诸其身</strong></li></ol><h3 id="理-为什么值得读" tabindex="-1">理：为什么值得读 <a class="header-anchor" href="#理-为什么值得读" aria-label="Permalink to &quot;理：为什么值得读&quot;">​</a></h3><ul><li><strong>「素其位」是极实用的功夫</strong>：朱注说「无慕乎其外之心」——把手头这一位、这一事做好，而不是把心思用在「如果我在别处」。它与第 13 章「道不远人」同一条路：道在手边。</li><li><strong>「不陵下、不援上」是一对</strong>：对下不欺、对上不攀，两个方向都不越位。这一句把「守分」说得很具体。</li><li><strong>「居易」与「行险」是两种活法</strong>：一个走平路等时机，一个走险路赌运气。选择哪一条，本身就是判断。</li><li><strong>「反求诸其身」是归因的方向</strong>：射不中靶，先查自己的姿势，而不是怪靶子。这一句与第 13 章「以责人之心责己」互为表里，是全篇最常用的自省句式。</li></ul><h3 id="用-今日可用之处" tabindex="-1">用：今日可用之处 <a class="header-anchor" href="#用-今日可用之处" aria-label="Permalink to &quot;用：今日可用之处&quot;">​</a></h3><ol><li><strong>素位</strong>：先把眼前的位置做好，再谈「换个环境」。</li><li><strong>不陵下、不援上</strong>：两句话就可以当每日的自检。</li><li><strong>居易俟命</strong>：把力气用在平路上，而不是赌一把。</li><li><strong>反求诸身</strong>：事情不顺时，先把「怪谁」的念头放下，查自己。</li></ol><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><p>君子做事有一个总原则：**安于现在的位置，不羡慕别人的位置。**富贵处就按富贵处该做的做，贫贱处就按贫贱处该做的做，在患难里也一样——<strong>走到哪里都安然自得</strong>。</p><p>往上不欺下、往下不攀上；端正自己而无所求，于是上不怨天、下不尤人。 君子走平路、等时机；小人走险路、赌运气。</p><p>最后孔子打了个比方：<strong>射箭像君子——射不中靶，回头查自己。</strong></p><p>这一章的功夫，就在最后那一转身。</p><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><blockquote><p>待补——这一节留给自己的读后想法。</p></blockquote><p>可以按这几条慢慢写：</p><ul><li>「素其位而行」——我现在的「位」是什么？我在这个位上做好了吗？</li><li>「不陵下，不援上」——这两条，哪一条我守得更差？</li><li>「失诸正鹄，反求诸其身」——最近一件不顺的事，我先把责任放在谁身上了？</li><li>「居易以俟命」与「行险以徼幸」——我更像哪一种？</li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li><a href="/Dao/lizhimingde/sishu-wujing/zhongyong/">中庸总览</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/">四书五经总览</a></li><li>同栏目：<a href="/Dao/lizhimingde/sishu-wujing/daxue/">大学</a> · <a href="/Dao/lizhimingde/sishu-wujing/lunyu/">论语</a> · <a href="/Dao/lizhimingde/sishu-wujing/mengzi/">孟子</a></li><li>上章：<a href="/Dao/lizhimingde/sishu-wujing/zhongyong/chapter-13">中庸·第13章</a>　下章：<a href="/Dao/lizhimingde/sishu-wujing/zhongyong/chapter-15">中庸·第15章</a></li><li>参考：《礼记》第三十一篇；朱熹《四书章句集注·中庸章句》</li></ul>',24))])}}});export{b as __pageData,x as default};
